import React from 'react';

const Ahorro = ({ targetAmount, weeklySavings }) => {
    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <p><strong>Objetivo:</strong> {targetAmount || 'No disponible'}</p>
                <p><strong>Cantidad Semanal:</strong> {weeklySavings || 'No disponible'}</p>
            </div>
        </div>
    );
};

export default Ahorro;
